<?php
$a = [5, 3, 8, 1, 9, 2];
sort($a); echo implode(",", $a), "\n"; rsort($a); echo implode(",", $a), "\n";
$assoc = ['banana' => 3, 'apple' => 1, 'cherry' => 2];
asort($assoc); print_r($assoc); arsort($assoc); print_r($assoc); ksort($assoc); print_r($assoc); krsort($assoc); print_r($assoc);
$people = [['name' => 'Bob', 'age' => 25], ['name' => 'Alice', 'age' => 30], ['name' => 'Carol', 'age' => 25]];
usort($people, fn($x, $y) => $x['age'] <=> $y['age']); echo implode(",", array_column($people, 'name')), "\n";
uasort($assoc, fn($x, $y) => $y - $x); print_r($assoc); uksort($assoc, 'strcmp'); print_r($assoc);
$mixed = ["10", 9, "9a", 1.5, true, null, "abc"]; sort($mixed); var_dump($mixed);
$strs = ["b10", "a2", "a10", "B1"]; sort($strs); print_r($strs); natsort($strs); print_r($strs); natcasesort($strs); print_r($strs); sort($strs, SORT_NATURAL | SORT_FLAG_CASE); print_r($strs);
sort($strs, SORT_STRING); print_r($strs);
print_r(array_merge([1, 2], ['a' => 1], [3], ['a' => 2]));
print_r([1, 2] + [5, 6, 7]); print_r(array_combine(['x', 'y'], [1, 2])); print_r(array_flip(['a' => 1, 'b' => 2]));
