print_r(array_count_values(['a', 'b', 'a', 1, '1']));
print_r(array_diff([1, 2, 3, 4], [2, 4])); print_r(array_intersect(['a' => 1, 'b' => 2, 'c' => 3], [2, 3])); print_r(array_diff_key(['a' => 1, 'b' => 2], ['a' => 9])); print_r(array_intersect_key(['a' => 1, 'b' => 2], ['b' => 0]));
