print_r(array_keys(['a' => 1, 'b' => 2, 'c' => 1], 1)); print_r(array_values(['x' => 'a', 'y' => 'b']));
$stack = [1, 2]; array_push($stack, 3, 4); echo array_pop($stack), array_shift($stack), count($stack), "\n"; array_unshift($stack, 0); print_r($stack);
$q = [5 => 'a', 6 => 'b']; array_shift($q); print_r($q); $q[] = 'c'; print_r($q);
print_r(array_map(null, [1, 2], ['a', 'b'])); print_r(array_map(fn($a, $b) => $a . $b, [1, 2], ['x', 'y']));
print_r(array_map(fn($x) => $x * 10, ['a' => 1, 'b' => 2])); print_r(array_filter([0, 1, '', null, 'a', false, [], '0']));
print_r(array_filter(['a' => 1, 'b' => 2, 'c' => 3], fn($k) => $k != 'b', ARRAY_FILTER_USE_KEY));
$w = [1, 2, 3]; array_walk($w, function(&$v, $k) { $v = $v * 10 + $k; }); print_r($w);
echo count([1, [2, 3]], COUNT_RECURSIVE), " ", array_key_first(['x' => 1, 'y' => 2]), array_key_last(['x' => 1, 'y' => 2]), "\n";
var_dump(array_is_list([1, 2]), array_is_list([1 => 1]), array_key_exists('a', ['a' => null]), isset(['a' => null]['a']));
$arr = [3 => 'c', 1 => 'a']; echo current($arr), key($arr), next($arr), key($arr), var_export(next($arr), true), reset($arr), end($arr), "\n";
